'use strict';
const LEVELS={junior:'國中基礎',senior:'高中進階',college:'大學應用'};
const KEY='english-steps-progress-v1';
const $=s=>document.querySelector(s);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={};let persistent=true;let filter='all';let activeId=null;let opener=null;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');if(raw&&typeof raw==='object'&&!Array.isArray(raw))saved=raw;}catch{persistent=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{persistent=false;}}
function updateProgress(){const count=LESSONS.filter(l=>saved[l.id]===true).length;$('#progress-text').textContent=persistent?(count?`已完成 ${count} 課，繼續走下一步。`:'準備好，開始你的第一步'):'無法儲存至瀏覽器，本次仍可練習。';$('#progress-count').textContent=`${count} / ${LESSONS.length}`;$('#progress-fill').style.width=`${count/LESSONS.length*100}%`;const next=LESSONS.find(l=>!saved[l.id])||LESSONS[0];$('#continue').href=`#lesson/${next.id}`;$('#continue').innerHTML=count===LESSONS.length?'再次複習課程 <span>↗</span>':count?'繼續下一課 <span>↗</span>':'開始第一課 <span>↗</span>';}
function renderCards(){const query=$('#search').value.trim().toLowerCase();const list=LESSONS.filter(l=>(filter==='all'||l.level===filter)&&[l.title,l.grammar,...l.vocabulary.map(v=>v.word+' '+v.meaning)].join(' ').toLowerCase().includes(query));$('#result-count').textContent=`顯示 ${list.length} 堂課程`;$('#empty').hidden=list.length>0;$('#course-grid').innerHTML=list.map(l=>`<article class="course-card"><div class="card-meta"><span>${LEVELS[l.level]}</span><span>LESSON ${String(l.order).padStart(2,'0')}</span></div><h3>${esc(l.title)}</h3><p>${esc(l.goals[0])}</p><div class="card-bottom"><span>${saved[l.id]?'✓ 已完成':`◷ ${l.minutes} 分鐘 · ${l.quiz.length} 題練習`}</span><button data-open="${l.id}" aria-label="學習${esc(l.title)}">${saved[l.id]?'再次複習':'開始學習'} ↗</button></div></article>`).join('');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(b=>{const selected=b.dataset.filter===value;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});renderCards();}
function openLesson(id){const l=LESSONS.find(l=>l.id===id);if(!l)return;opener=document.activeElement;activeId=id;$('#lesson-label').textContent=`${LEVELS[l.level]} / LESSON ${String(l.order).padStart(2,'0')} / 約 ${l.minutes} 分鐘`;$('#lesson-content').innerHTML=`<article class="lesson-body"><h2 id="lesson-title">${esc(l.title)}</h2><p>${l.goals.map(esc).join('／')}</p><h3>01 學習單字</h3><div class="vocab">${l.vocabulary.map(v=>`<div><strong>${esc(v.word)}</strong><small>${esc(v.meaning)}</small></div>`).join('')}</div><h3>02 理解重點</h3><p>${esc(l.grammar)}</p><h3>03 看懂例句</h3>${l.examples.map(e=>`<div class="example"><p lang="en">${esc(e.en)}</p><p>${esc(e.zh)}</p></div>`).join('')}<h3>04 換你練習</h3><form id="quiz-form">${l.quiz.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${esc(q.question)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="q${i}" value="${j}" required>${esc(o)}</label>`).join('')}<div id="feedback-${i}" aria-live="polite"></div></fieldset>`).join('')}<button class="button dark" type="submit">檢查答案 ↗</button><p id="quiz-status" role="status">答對全部題目，再完成下方輸出練習。</p></form><h3>05 用自己的話說</h3><ul>${l.task.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><label><input type="checkbox" id="task-done"> 我已完成造句與朗讀練習</label><div class="completion"><button class="button dark" id="mark-done" disabled>標記本課完成 ✓</button><span id="done-status" role="status"></span></div><p class="lesson-source">${esc(l.sourceNote)}${l.sources.length?'<br>'+l.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join(' · '):''}</p></article>`;
let passed=false;const enable=()=>{$('#mark-done').disabled=!(passed&&$('#task-done').checked);};$('#task-done').addEventListener('change',enable);$('#quiz-form').addEventListener('submit',e=>{e.preventDefault();let correct=0;const data=new FormData(e.currentTarget);l.quiz.forEach((q,i)=>{const ok=Number(data.get('q'+i))===q.answer;if(ok)correct++;const f=$('#feedback-'+i);f.className='feedback'+(ok?'':' wrong');f.textContent=`${ok?'✓ 答對了':'再想一想'}。正確答案：${q.options[q.answer]}。${q.explanation}`;});passed=correct===l.quiz.length;$('#quiz-status').textContent=`本次答對 ${correct} / ${l.quiz.length} 題。${passed?'完成輸出練習後即可標記完成。':'可修改答案，再試一次。'}`;enable();});$('#quiz-form').addEventListener('change',()=>{passed=false;enable();$('#quiz-status').textContent='答案已變更，請重新檢查答案。';});$('#mark-done').addEventListener('click',()=>{saved[id]=true;persist();updateProgress();renderCards();$('#done-status').textContent=persistent?'已完成並儲存！關閉視窗後可選下一課。':'本次已完成；瀏覽器無法保存進度。';$('#mark-done').disabled=true;});if(!$('#lesson-dialog').open)$('#lesson-dialog').showModal();$('#lesson-dialog').scrollTop=0;}
function route(){if(location.hash.startsWith('#lesson/'))openLesson(decodeURIComponent(location.hash.slice(8)));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open]');if(b){location.hash='lesson/'+b.dataset.open;}const f=e.target.closest('[data-filter]');if(f)setFilter(f.dataset.filter);const r=e.target.closest('[data-level-link]');if(r){setFilter(r.dataset.levelLink);$('#search').value='';renderCards();location.hash='courses';}});
$('#search').addEventListener('input',renderCards);$('#reset').addEventListener('click',()=>{if(confirm('確定要清除這個瀏覽器中的所有完成紀錄嗎？')){saved={};persist();updateProgress();renderCards();}});
$('#close-dialog').addEventListener('click',()=>$('#lesson-dialog').close());$('#lesson-dialog').addEventListener('close',()=>{if(activeId){activeId=null;history.replaceState(null,'',location.pathname+location.search+'#courses');}if(opener instanceof HTMLElement)opener.focus();});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#lesson/'))route();else if($('#lesson-dialog').open)$('#lesson-dialog').close();});updateProgress();renderCards();route();
